429:         invocation.request as ExactStartRunInvocation["request"],
430:       ) ?? {
431:         kind: "start",
432:         scope: "program",
433:         target: "",
434:         until: "converged",
435:         rootMode: "direct",
436:       };
437:   if (
438:     (selection.kind === "direct" && selection.catalogHandle.length === 0) ||
439:     (selection.kind === "start" && selection.target.length === 0)
440:   ) {
441:     return preparationRefusal(memberKey, "invalid_target", ["/target"]);
442:   }
443:   const resolution = await ProductExecutionResolutionPort.resolve({
444:     catalog: resources.catalog,
